function questionPlan(id){const all=[];FORMS[id].forEach((g,gi)=>{if(g.kind==='findings')for(let i=1;i<=3;i++)all.push({type:'finding',key:'s3_f'+i,label:'Finding '+i,q:`What is finding ${i}, and what kind of support is underneath it?`,hint:'Keep its source and context beside it. The rung is a prompt to inspect, not a quality seal.',rung:'s3_r'+i,group:gi});if(g.kind==='logic')all.push({type:'logic',key:'s3_pre',q:'Imagine it failed a year from now. What is the most plausible reason?',hint:'Challenge the logic before defending the recommendation.',group:gi});if(g.kind==='thread')all.push({type:'thread',key:'s4_where',q:'Does the purpose survive all five checks?',hint:'Check a pin when you have inspected it. Leave the unanswered ones visible.',group:gi});if(g.kind==='review')all.push({type:'review',key:'s5_review',q:'Make one pass through the five review moves.',hint:'Use these prompts to guide the conversation. Then record the decision and reasons once for the handover.',group:gi});if(g.kind==='radar')all.push({type:'radar',key:'s6_a1',q:'Would this offer be easy for this client to adopt?',hint:'Score each lens from 1 (weak or unclear) to 5 (clear and supported). The scores start a conversation.',group:gi});g.fields.forEach(([key,label,hint])=>{if(key==='s3_pre')return;const copy=QUESTIONS[key]||[label,hint];all.push({type:'text',key,label,q:copy[0],hint:copy[1],group:gi})});if(g.kind==='qualifier')all.push({type:'qualifier',key:'s2_q',q:'How certain is the frame right now?',hint:'Make the uncertainty explicit. A best guess can still be useful.',group:gi});if(g.kind==='ledger')all.push({type:'ledger',key:'s0_c1',q:'What would close the gap, and what should the next person know?',hint:'Choose a response, then leave a record of the framing decision.',group:gi})});return all}
